-- Queryopsy case database: Funding Forensics
-- Source: data/samples/funding_placeholder.csv (PLACEHOLDER - synthetic)
-- Generated by pipeline/build.py - do not edit by hand.

-- One row per reported funding round (cleaned dates/amounts, raw city text kept on purpose).
CREATE TABLE funding_rounds (
  round_id INTEGER PRIMARY KEY,
  deal_date TEXT,
  startup TEXT,
  vertical TEXT,
  city_raw TEXT,
  investors TEXT,
  round_type TEXT,
  amount_usd INTEGER,
  amount_raw TEXT
);

-- One row per (round, investor) - split from funding_rounds.investors.
CREATE TABLE round_investors (
  round_id INTEGER REFERENCES funding_rounds(round_id),
  investor TEXT
);

